window.HS_DATA=[{"id": 1, "tag": "부도 수표", "facts": "피고인 甲은 부도수표를 발행하였다는 부정수표단속법위반으로 기소되었다.", "ev": "검사가 증거로 제출한, 지급거절 표시가 있는 甲 발행의 수표 원본", "kind": "비진술", "notes": ["부도수표는 그 서류의 존재 또는 상태 자체가 증거가 되는 증거물인 서면이고, 어떤 사실을 경험한 사람의 진술을 대신하는 것이 아니므로 전문법칙이 적용될 여지가 없다.", "증거물인 서면이므로 제시와 함께 낭독·내용고지·열람의 방법으로 조사한다."], "cases": ["2015도2275"]}, {"id": 2, "tag": "업무일지 뒷면", "facts": "피고인 甲은 사문서위조·사기로 기소되었다. 회사 직원 乙은 민사소송 준비를 위해 회사에 보관된 업무일지를 가져와 검토하다가, 그 뒷면에서 甲이 다른 사람의 서명을 연습한 흔적을 발견하고 이를 수사기관에 냈다.", "ev": "甲의 서명 위조 연습 흔적이 남은 업무일지 뒷면", "kind": "비진술", "notes": ["서명을 연습한 흔적은 그 존재 자체가 위조 범행을 증명하는 것이지, 누군가의 진술을 내용으로 하는 것이 아니다.", "사인이 회사 문서를 가져와 수집한 증거라도 증거능력이 인정된 사례이다."], "cases": ["2008도1584"]}, {"id": 3, "tag": "혈흔이 묻은 침대시트", "facts": "피고인 甲에 대한 사건에서, 乙은 이미 거주가 끝난 타인의 주거에 들어가 혈흔이 묻은 휴지와 침대시트를 가져와 수사기관에 냈다.", "ev": "혈흔이 묻은 휴지와 침대시트", "kind": "비진술", "notes": ["혈흔이 묻은 물건은 진술이 아닌 증거물이다.", "사인이 위법하게 수집한 증거라도 공익과 사생활 보호를 비교형량하여 증거능력을 인정할 수 있고, 이 사안은 증거능력이 인정되었다."], "cases": ["2008도3990", "2010도12244"]}, {"id": 4, "tag": "촬영된 사진", "facts": "피고인 甲에 대한 사건에서, 乙이 甲의 모습을 촬영한 사진이 증거로 제출되었다. 甲은 사진 촬영 당시 자신이 무의식 상태였고 乙이 다른 목적으로 촬영하였다고 다툰다.", "ev": "乙이 甲의 모습을 촬영한 사진", "kind": "비진술", "notes": ["사진은 사람의 진술이 아니라 촬영된 대상의 모습을 담은 증거물이다. 위법하게 수집된 것이 아니면 제318조 제1항 증거동의의 대상이 된다.", "촬영 당시 무의식 상태였다는 등의 주장은 증명력을 다투는 것일 뿐 증거동의의 효력과는 관계없다."], "cases": ["97도1230"]}, {"id": 5, "tag": "공범의 경찰 진술", "facts": "피고인 甲과 乙은 함께 금고를 턴 특수절도 공범으로, 함께 기소되어 병합심리 중인 공동피고인이다. 乙은 경찰 조사에서 \"甲과 함께 금고를 털었다\"고 진술하였고, 甲은 법정에서 이 조서의 내용을 부인한다.", "ev": "사법경찰관이 작성한 乙에 대한 피의자신문조서", "kind": "전문", "notes": ["제312조 제3항은 당해 피고인과 공범관계에 있는 다른 피의자에 대한 사경 작성 피의자신문조서에도 적용된다.", "乙이 법정에서 성립의 진정을 인정하더라도 甲이 내용을 부인하면 증거능력이 없고, 乙이 사망 등으로 진술할 수 없어도 제314조는 적용되지 않는다."], "cases": ["2009도14409", "2009도6602"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "공범인 공동피고인", "alt": [], "by": "사경 등", "why": "공범인 공동피고인(乙)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서"}, {"id": 6, "tag": "공범의 검찰 진술", "facts": "피고인 甲과 乙은 사기 공범으로, 함께 기소되어 병합심리 중인 공동피고인이다. 乙은 검사 앞에서 \"甲의 지시로 피해자를 속였다\"고 진술하였고, 甲은 이 조서의 내용을 부인한다.", "ev": "검사가 작성한 乙에 대한 피의자신문조서", "kind": "전문", "notes": ["제312조 제1항의 '검사가 작성한 피의자신문조서'에는 당해 피고인과 공범관계에 있는 다른 피고인·피의자에 대한 조서도 포함된다.", "따라서 甲이 내용을 부인하면 유죄의 증거로 쓸 수 없다."], "cases": ["2023도3741"], "law": "제312조 제1항", "opts": ["제311조", "제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "없음"], "form": "피의자신문조서", "a": "공범인 공동피고인", "alt": [], "by": "검사", "why": "공범인 공동피고인(乙)의 진술을 내용으로 하는 검사 작성의 피의자신문조서"}, {"id": 7, "tag": "뇌물을 준 사람의 진술", "facts": "공무원인 피고인 甲은 뇌물수수로 기소되었다. 뇌물을 준 乙은 뇌물공여로 따로 기소되어 별도로 재판받고 있다(공동피고인 아님). 乙은 검사 앞에서 \"甲에게 500만 원을 주었다\"고 진술하였고, 甲은 이 조서의 내용을 부인한다.", "ev": "검사가 작성한 乙에 대한 피의자신문조서", "kind": "전문", "notes": ["제312조의 '공범'에는 형법총칙의 공범뿐 아니라 뇌물공여자·수수자와 같은 대향범(필요적 공범)도 포함된다.", "그러므로 乙에 대한 검사 작성 피의자신문조서는 제312조 제1항에 따라 甲이 내용을 부인하면 증거로 쓸 수 없다."], "cases": ["2023도3741", "85도691"], "law": "제312조 제1항", "opts": ["제311조", "제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "없음"], "form": "피의자신문조서", "a": "공범", "alt": [], "by": "검사", "why": "공범(乙)의 진술을 내용으로 하는 검사 작성의 피의자신문조서"}, {"id": 8, "tag": "훔친 노트북을 산 사람", "facts": "피고인 甲은 장물취득으로, 乙은 절도로 함께 기소되어 병합심리 중이다. 乙은 경찰 조사에서 \"훔친 노트북을 甲에게 팔았다\"고 진술하였다.", "ev": "사법경찰관이 작성한 공동피고인 乙에 대한 피의자신문조서", "kind": "전문", "notes": ["본범(절도범)과 장물범은 공범이 아니므로 제312조 제3항이 아니라 피고인 아닌 자의 진술을 기재한 조서로서 제312조 제4항이 적용된다.", "甲이 증거로 함에 동의하지 않으면, 乙이 법정에서 증언하여 성립의 진정을 인정하는 등 그 요건을 갖추어야 증거로 쓸 수 있다."], "cases": ["2005도7601"], "law": "제312조 제4항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "없음"], "form": "진술조서", "a": "공동피고인", "alt": [], "by": "사경 등", "why": "공동피고인(乙)의 진술을 내용으로 하는 사경 등 작성의 진술조서 — 형식은 피의자신문조서이나 실질은 진술조서"}, {"id": 9, "tag": "검사 명의의 조서", "facts": "피고인 甲에 대한 피의자신문조서는 검사 명의로 되어 있으나, 실제로는 검찰주사가 검사 없이 甲을 신문하여 작성하였고 검사는 개괄적으로 질문만 하였다. 조서에는 甲이 범행을 자백한 내용이 적혀 있고, 甲은 법정에서 그 내용을 부인한다.", "ev": "검사 명의로 작성된 甲에 대한 피의자신문조서", "kind": "전문", "notes": ["외관상 검사가 작성한 것으로 되어 있어도 검사가 피의자를 직접·개별적으로 신문하지 않았다면, 검사 이외의 수사기관이 작성한 피의자신문조서의 기준(제312조 제3항)이 적용된다."], "cases": ["2002도4372"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서"}, {"id": 10, "tag": "경찰서에서 쓴 자술서", "facts": "사법경찰관은 피의자 甲을 조사하면서 피의자신문조서를 작성하는 대신, 甲에게 \"제가 가게에서 돈을 훔쳤습니다\"라는 내용의 자술서를 쓰게 하여 제출받았다.", "ev": "甲이 경찰서에서 작성한 자술서", "kind": "전문", "notes": ["피의자신문조서에 기재되어야 할 피의자의 진술을 진술서 형식으로 받은 경우, 그 진술서의 증거능력은 제313조 제1항이 아니라 사경 작성 피의자신문조서와 같이 제312조 제3항(제312조 제5항이 준용)에 따라 정한다."], "cases": ["82도1479"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서 — 자술서 형식이지만 피의자신문조서에 준하는 것"}, {"id": 11, "tag": "압수조서 속 자백", "facts": "사법경찰관이 작성한 압수조서의 압수경위란에 \"피의자 甲은 '필로폰을 투약하였다'고 자백하였다\"는 기재가 있다. 甲은 법정에서 공소사실을 부인하며 경찰 피의자신문조서의 내용도 부인한다.", "ev": "사법경찰관 작성 압수조서 중 甲의 자백 진술 기재 부분", "kind": "전문", "notes": ["수사기관의 수사과정에서 작성된 피의자의 진술 기재 서류는 형식이 무엇이든 피의자신문조서와 달리 볼 이유가 없다(피의자신문조서에 준하는 것).", "따라서 압수조서에 적힌 피고인의 자백 부분은 피고인이 내용을 부인하면 증거능력이 없다."], "cases": ["2020도16796"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서"}, {"id": 12, "tag": "경찰 검증조서 속 범행 재연", "facts": "사법경찰관이 작성한 검증조서에는 현장 상황 외에 甲이 범행을 재연한 사진과 \"이렇게 피해자를 밀었다\"는 甲의 진술이 기재되어 있다. 甲은 법정에서 이 부분의 내용을 부인한다.", "ev": "사경 작성 검증조서 중 甲의 진술 기재 및 범행 재연 부분", "kind": "전문", "notes": ["사경 작성 검증조서 중 범행에 부합하는 '피고인의 진술 기재 부분'과 '범행 재연 부분'은 피고인이 내용을 인정하는 경우에만 증거능력이 있다(피의자신문조서에 준함).", "현장 상황 부분은 검증조서(제312조 제6항)로서 따로 판단한다."], "cases": ["98도159", "90도1303"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서 — 검증조서 중 진술 기재·범행 재연 부분"}, {"id": 13, "tag": "목격자의 경찰 진술", "facts": "피고인 甲은 상해로 기소되었다. 목격자 丙은 경찰에서 \"甲이 피해자를 주먹으로 때리는 것을 보았다\"고 진술하였고, 甲은 증거로 함에 동의하지 않는다.", "ev": "사법경찰관이 작성한 丙에 대한 진술조서", "kind": "전문", "notes": ["피고인 아닌 자의 진술을 기재한 조서는 적법한 절차와 방식, 원진술자의 진술 등에 의한 실질적 진정성립, 반대신문 기회, 특신상태를 갖추어야 한다.", "원진술자가 조서 내용을 열람·고지받지 못한 채 \"수사기관에서 사실대로 진술하였다\"고만 증언한 것으로는 부족하다."], "cases": ["2015도12981", "94도343"], "law": "제312조 제4항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "없음"], "form": "진술조서", "a": "피고인 아닌 자", "alt": [], "by": "사경 등", "why": "피고인 아닌 자(목격자 丙)의 진술을 내용으로 하는 사경 등 작성의 진술조서"}, {"id": 14, "tag": "검찰청에서 쓴 진술서", "facts": "피해자 丁은 검찰청에 소환된 상태에서 검사의 요구로 피해 경위를 적은 진술서를 작성하였다. 검사는 그 구체적 내용에는 관여하지 않았다.", "ev": "丁이 검찰청에서 작성한 진술서", "kind": "전문", "notes": ["검사의 요구로 수사과정에서 작성된 진술서는 검사가 내용에 관여하지 않았더라도 제312조 제5항의 '피고인이 아닌 자가 수사과정에서 작성한 진술서'에 해당한다.", "수사기관이 조사과정을 기록하지 않았다면(제244조의4) 적법한 절차와 방식에 따라 작성되었다고 할 수 없어 증거능력이 없다."], "cases": ["2013도3790", "2022도9510"], "law": "제312조 제5항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제5항", "제313조 제1항", "제315조 제3호", "없음"], "form": "수사기관에서 작성한 진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(피해자 丁)가 검사의 수사과정에서 작성한 진술서"}, {"id": 15, "tag": "압수경위란의 목격 기재", "facts": "경찰관 A는 지하철에서 甲이 휴대전화로 여성의 신체를 몰래 촬영하는 것을 직접 보고 현행범으로 체포하였다. A가 작성한 압수조서의 압수경위란에는 그 목격 내용이 적혀 있다. 甲은 이 압수조서를 증거로 함에 동의하였다.", "ev": "압수조서 중 압수경위란의 기재 부분", "kind": "전문", "notes": ["압수경위란의 기재는 범행 현장을 직접 목격한 경찰관의 진술이 담긴 것으로, 제312조 제5항의 '피고인이 아닌 자가 수사과정에서 작성한 진술서'에 준한다.", "임의제출 절차의 적법 여부와 관계없는 독립된 증거이므로, 피고인이 증거동의한 이상 증거능력이 있고 자백의 보강증거도 된다."], "cases": ["2019도13290"], "law": "제312조 제5항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제5항", "제313조 제1항", "제315조 제3호", "없음"], "form": "수사기관에서 작성한 진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(경찰관 A)가 사경 등의 수사과정에서 작성한 진술서"}, {"id": 16, "tag": "동료 교사가 녹음한 학생들 대화", "facts": "피고인 甲은 국가보안법위반으로 기소되었다. 동료 교사 B는 학생들끼리 \"甲 선생님이 수업시간에 북한을 찬양하는 말을 했다\"고 이야기하는 것을 학생들 몰래 녹음하였다. 甲은 녹음테이프를 증거로 함에 동의하지 않는다.", "ev": "학생들의 대화가 녹음된 녹음테이프(학생들 진술 부분)", "kind": "전문", "notes": ["녹음테이프에 녹음된 학생들의 대화는 실질적으로 제311조·제312조 이외의 피고인 아닌 자의 진술을 기재한 서류와 다를 바 없다(진술 기재 서류 → 진술조서에 준하는 것).", "따라서 제313조 제1항에 따라 원진술자인 학생들의 진술로 자신이 진술한 대로 녹음된 것임이 인정되어야 한다. 법원의 녹음테이프 검증조서도 증거자료는 녹음된 대화 내용이므로 같다."], "cases": ["96도2417"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술을 기재한 서류", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(학생들)의 진술을 내용으로 하는 진술을 기재한 서류"}, {"id": 17, "tag": "상대방이 녹음한 대화", "facts": "乙은 甲과 대화하면서 그 내용을 몰래 녹음하였다. 녹음에는 甲이 \"그 돈은 내가 받았다\"고 말하는 부분이 있다. 甲은 녹음파일을 증거로 함에 동의하지 않는다.", "ev": "乙이 녹음한 대화 녹음파일 중 甲의 진술 부분", "kind": "전문", "notes": ["녹음된 피고인의 진술은 실질적으로 피고인의 진술을 기재한 서류와 다름없다(진술 기재 서류 → 진술조서에 준하는 것).", "제313조 제1항 단서에 따라 작성자인 녹음자 乙의 진술로 피고인이 진술한 대로 녹음된 것임이 증명되고 특신상태가 인정되어야 한다. 사본이면 원본 그대로 복사된 것임도 증명되어야 한다."], "cases": ["2012도7461"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술을 기재한 서류", "a": "피고인", "alt": [], "why": "피고인(甲)의 진술을 내용으로 하는 진술을 기재한 서류"}, {"id": 18, "tag": "점검단원이 쓴 확인서", "facts": "정부합동공직복무점검단 소속 점검단원 C는 공무원 甲을 면담하면서 \"업체로부터 향응을 받았다\"는 甲의 진술을 확인서에 적었다. 甲은 이 확인서를 증거로 함에 동의하지 않는다.", "ev": "점검단원 C가 작성한, 甲의 진술을 기재한 확인서", "kind": "전문", "notes": ["수사기관이 아닌 자가 피고인의 진술을 기재한 서류이다(진술 기재 서류 → 진술조서에 준하는 것).", "제313조 제1항 단서에 따라 작성자 C의 진술로 진술대로 기재되었음이 증명되고 특신상태가 인정되어야 한다. 이 사안은 증거능력이 인정되었다."], "cases": ["2018도3914"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술을 기재한 서류", "a": "피고인", "alt": [], "why": "피고인(甲)의 진술을 내용으로 하는 진술을 기재한 서류"}, {"id": 19, "tag": "법무법인의 법률의견서", "facts": "회사 대표 甲은 배임으로 기소되었다. 법무법인 소속 변호사 D가 회사의 의뢰로 작성해 보낸 법률의견서가 압수되어 증거로 제출되었고, D는 법정에서 변호사의 업무상 비밀을 이유로 증언을 거부하였다.", "ev": "변호사 D가 작성한 법률의견서", "kind": "전문", "notes": ["피고인 아닌 자(변호사)가 작성한 진술서이므로 제313조 제1항이 적용된다.", "작성자가 제149조에 따라 정당하게 증언거부권을 행사한 것은 제314조의 '그 밖에 이에 준하는 사유로 진술할 수 없는 때'에 해당하지 않으므로, 제314조로도 증거능력을 인정할 수 없다."], "cases": ["2009도6788"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(변호사 D)가 작성한 진술서"}, {"id": 20, "tag": "자살 직전 쓴 유서", "facts": "피고인 甲과 丙은 합동하여 저지른 성범죄로 기소되었다. 함께 범행한 것으로 지목된 乙은 범행 후 14년이 지나 기소되기 전에 자살하였는데, 자살 직전 \"甲, 丙과 함께 범행하였다\"는 유서를 남겼다.", "ev": "乙이 작성한 유서", "kind": "전문", "notes": ["유서는 피고인 아닌 자가 작성한 진술서인데, 작성자가 사망하여 법정에서 진술할 수 없으므로 제314조의 요건(특신상태)을 갖추어야 한다.", "제314조의 특신상태는 합리적 의심의 여지를 배제할 정도로 증명되어야 한다. 이 사안은 14년 이상 지난 뒤 작성되었고 구체적 기재가 없어 특신상태가 부정되어 증거능력이 없었다."], "cases": ["2023도13406", "2013도12652"], "law": "제314조", "opts": ["제312조 제4항", "제313조 제1항", "제314조", "제316조 제2항", "제318조 제1항", "없음"], "form": "진술서", "law2": "제313조 제1항", "a": "공범", "alt": [], "why": "공범(망인 乙)이 작성한 진술서"}, {"id": 21, "tag": "소재불명이 된 목격자", "facts": "피고인 甲의 상해 사건에서 목격자 丙의 경찰 진술조서가 제출되었다. 丙은 증인소환장이 송달되지 않았고, 검사는 소재탐지와 구인장 집행 등 법정 출석을 위한 가능하고도 충분한 노력을 다하였으나 丙을 찾지 못하였다.", "ev": "사법경찰관이 작성한 丙에 대한 진술조서", "kind": "전문", "notes": ["원진술자가 소재불명 등으로 진술할 수 없는 때에는 제314조에 따라 특신상태가 증명되어야 증거능력이 있다.", "소재불명은 검사가 출석을 위해 가능하고도 충분한 노력을 다했음을 증명해야 인정되고(구인장 집행불능 서면 제출만으로는 부족), 특신상태도 합리적 의심의 여지를 배제할 정도여야 한다."], "cases": ["2013도1435", "2006도7228", "2013도12652"], "law": "제314조", "opts": ["제312조 제4항", "제313조 제1항", "제314조", "제316조 제2항", "제318조 제1항", "없음"], "form": "진술조서", "law2": "제312조 제4항", "a": "피고인 아닌 자", "alt": [], "by": "사경 등", "why": "피고인 아닌 자(목격자 丙)의 진술을 내용으로 하는 사경 등 작성의 진술조서"}, {"id": 22, "tag": "치매로 기억을 잃은 피해자", "facts": "피고인 甲의 사기 사건에서 노인인 피해자 戊의 경찰 진술조서가 제출되었다. 戊는 그 뒤 노인성 치매로 기억력과 분별력을 잃어 법정에서 진술할 수 없다.", "ev": "사법경찰관이 작성한 戊에 대한 진술조서", "kind": "전문", "notes": ["노인성 치매로 인한 기억력 장애·분별력 상실은 제314조의 '질병'에 해당한다(출산을 앞둔 것은 해당하지 않음).", "그러므로 특신상태가 증명되면 제314조에 따라 증거능력이 인정될 수 있다."], "cases": ["91도2281", "99도915"], "law": "제314조", "opts": ["제312조 제4항", "제313조 제1항", "제314조", "제316조 제2항", "제318조 제1항", "없음"], "form": "진술조서", "law2": "제312조 제4항", "a": "피고인 아닌 자", "alt": [], "by": "사경 등", "why": "피고인 아닌 자(피해자 戊)의 진술을 내용으로 하는 사경 등 작성의 진술조서"}, {"id": 23, "tag": "당해 사건의 공판조서", "facts": "피고인 甲의 사건에서 판사가 바뀌어 공판절차가 갱신되었다. 갱신 전 공판조서에는 甲이 \"피해자를 때린 것은 맞다\"고 진술한 내용이 기재되어 있다.", "ev": "갱신 전 공판조서 중 甲의 진술 기재 부분", "kind": "전문", "notes": ["공판준비 또는 공판기일에 피고인이나 피고인 아닌 자의 진술을 기재한 조서는 제311조에 따라 당연히 증거능력이 있다(공판조서 → 진술조서에 준하는 것).", "다만 피고인의 공판조서 열람·등사청구권이 침해되었다면 그 공판조서와 거기 기재된 진술은 증거로 할 수 없다."], "cases": ["2003도3282", "2011도15869"], "law": "제311조", "opts": ["제311조", "제312조 제1항", "제313조 제1항", "제315조 제3호", "제316조 제1항", "없음"], "why": "법원 또는 법관의 조서"}, {"id": 24, "tag": "다른 사건의 증인신문조서", "facts": "피고인 甲의 사기 사건에서, 乙에 대한 별개 형사사건의 공판에서 증인 丙이 \"甲이 돈을 받아 가는 것을 보았다\"고 증언한 증인신문조서가 증거로 제출되었다.", "ev": "다른 사건 공판조서 중 丙의 증인신문조서", "kind": "전문", "notes": ["다른 피고인에 대한 형사사건의 공판조서(그 일부인 증인신문조서 포함)는 제315조 제3호의 서류로서 당연히 증거능력이 있다."], "cases": ["65도372"], "law": "제315조 제3호", "opts": ["제311조", "제312조 제4항", "제313조 제1항", "제314조", "제315조 제3호", "없음"], "why": "제315조 제3호 (또는 이에 준하는 것)"}, {"id": 25, "tag": "조사자의 법정증언", "facts": "피고인 甲은 살인미수로 기소되었다. 甲을 조사한 사법경찰관 A는 법정에 증인으로 나와 \"조사 때 甲이 '내가 피해자를 찔렀다'고 말했다\"고 증언하였다.", "ev": "조사자 A의 법정진술", "kind": "전문", "notes": ["피고인 아닌 자(조사자 포함)의 공판기일 진술이 피고인의 진술을 내용으로 하는 경우, 그 진술이 특히 신빙할 수 있는 상태에서 행하여졌음이 증명되면 증거로 할 수 있다(제316조 제1항)."], "cases": [], "law": "제316조 제1항", "opts": ["제312조 제3항", "제313조 제1항", "제314조", "제316조 제1항", "제316조 제2항", "없음"], "why": "피고인(甲)의 진술을 내용으로 하는 피고인 아닌 자(조사자 A)의 진술"}, {"id": 26, "tag": "공범의 법정진술", "facts": "피고인 甲과 乙은 공범으로 함께 기소되어 병합심리 중인 공동피고인이다. 乙은 법정에서 \"甲이 나에게 '돈을 받았다'고 말했다\"고 진술하였다.", "ev": "공동피고인 乙의 법정진술 중 甲의 말을 전한 부분", "kind": "전문", "notes": ["원진술자가 피고인 甲이므로 피고인의 진술을 내용으로 하는 전문진술로서 제316조 제1항(특신상태)에 따른다.", "공범인 공동피고인의 법정진술 자체는 반대신문권이 보장되어 독립한 증거능력이 있지만, 그 내용이 다른 사람의 말을 전하는 부분은 전문진술이다."], "cases": ["92도917", "2006도1944"], "law": "제316조 제1항", "opts": ["제312조 제3항", "제313조 제1항", "제314조", "제316조 제1항", "제316조 제2항", "없음"], "why": "피고인(甲)의 진술을 내용으로 하는 피고인 아닌 자(공범인 공동피고인 乙)의 진술"}, {"id": 27, "tag": "공범에게서 들은 말", "facts": "피고인 甲은 강도로 기소되었다. 증인 丙은 법정에서 \"공범 乙이 '甲과 같이 했다'고 말하는 것을 들었다\"고 증언하였다. 乙은 따로 기소되어 별도로 재판받고 있으며(공동피고인 아님), 이 사건 법정에 나와 진술할 수 있다.", "ev": "증인 丙의 법정진술", "kind": "전문", "notes": ["원진술자가 피고인 아닌 자(공범 포함)이면 제316조 제2항에 따라 원진술자가 사망·질병·소재불명 등으로 진술할 수 없고 특신상태가 있어야 증거능력이 있다.", "이 사안은 乙이 진술할 수 있으므로 丙의 전문진술은 증거능력이 없다. 그 사정을 고지하지 않은 채 증인신문이 진행되었다면 피고인이 \"별 의견 없다\"고 했더라도 증거동의로 볼 수 없다."], "cases": ["2019도11552", "2015도12981"], "law": "제316조 제2항", "opts": ["제313조 제1항", "제314조", "제316조 제1항", "제316조 제2항", "제318조 제1항", "없음"], "form": "진술", "a": "공범", "why": "공범(乙)의 진술을 내용으로 하는 피고인 아닌 자(증인 丙)의 진술"}, {"id": 28, "tag": "피해자가 전해 들은 목격담", "facts": "피고인 甲의 폭행 사건에서, 피해자 丁은 경찰에서 \"목격자 戊가 '甲이 당신을 미는 것을 보았다'고 말해 주었다\"고 진술하였다. 戊는 그 뒤 사망하였다.", "ev": "사법경찰관이 작성한 丁에 대한 진술조서 중 戊의 말을 전한 부분", "kind": "재전문", "notes": ["전문진술을 기재한 조서는 제312조 또는 제314조에 따라 증거능력이 인정될 수 있어야 할 뿐 아니라, 제316조 제2항의 요건(원진술자 진술불능 + 특신상태)도 갖추어야 예외적으로 증거능력이 있다.", "여기서는 조서 부분이 제312조 제4항, 원진술자 戊의 말을 전한 부분이 제316조 제2항이다."], "cases": ["2015도12981"], "law": "제312조 제4항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "auto": "제316조 제2항", "form": "진술조서", "a1": "피고인 아닌 자", "a2": "피고인 아닌 자", "alt": [], "by": "사경 등", "why": "피고인 아닌 자(목격자 戊)의 진술을 내용으로 하는 피고인 아닌 자(피해자 丁)의 진술이 기재된 사경 등 작성의 진술조서"}, {"id": 29, "tag": "참고인이 들은 피고인의 말", "facts": "피고인 甲의 방화 사건에서, 참고인 乙은 검사 앞에서 \"甲이 나에게 '내가 불을 질렀다'고 말했다\"고 진술하였다.", "ev": "검사가 작성한 乙에 대한 진술조서 중 甲의 말을 전한 부분", "kind": "재전문", "notes": ["피고인의 진술을 내용으로 하는 전문진술이 조서에 기재된 경우이다. 조서 부분은 제312조 제4항, 피고인 甲의 말을 전한 부분은 제316조 제1항(특신상태)의 요건을 함께 갖추어야 한다."], "cases": ["2015도12981"], "law": "제312조 제4항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "auto": "제316조 제1항", "form": "진술조서", "a1": "피고인", "a2": "피고인 아닌 자", "alt": [], "by": "검사", "why": "피고인(甲)의 진술을 내용으로 하는 피고인 아닌 자(참고인 乙)의 진술이 기재된 검사 작성의 진술조서"}, {"id": 30, "tag": "일기에 적은 피고인의 말", "facts": "피고인 甲의 절도 사건에서, 乙이 수사와 관계없이 평소 쓰던 일기장에 \"甲이 '내가 금고 비밀번호를 알아냈다'고 말했다\"고 적은 부분이 증거로 제출되었다.", "ev": "乙의 일기장 중 甲의 말을 적은 부분", "kind": "재전문", "notes": ["수사과정 외에서 피고인 아닌 乙이 작성한 진술서(제313조 제1항)에, 피고인 甲의 진술이 전문으로 기재된 경우이다.", "진술서 부분은 제313조 제1항, 甲의 말을 전한 부분은 제316조 제1항의 요건을 함께 갖추어야 한다."], "cases": ["2015도12981"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제315조 제3호", "없음"], "auto": "제316조 제1항", "form": "진술서", "a1": "피고인", "a2": "피고인 아닌 자", "alt": [], "why": "피고인(甲)의 진술을 내용으로 하는 피고인 아닌 자(乙)가 작성한 진술서"}, {"id": 31, "tag": "장물범의 조서 속 절도범의 말", "facts": "피고인 甲은 절도로 기소되었다. 장물취득으로 따로 조사받은 乙(공범도 공동피고인도 아님)은 경찰 피의자신문에서 \"甲이 노트북을 팔면서 '훔친 물건이다'라고 말했다\"고 진술하였다.", "ev": "사법경찰관이 작성한 乙에 대한 피의자신문조서 중 甲의 말을 전한 부분", "kind": "재전문", "notes": ["본범과 장물범은 공범이 아니므로 乙에 대한 피의자신문조서는 피고인 아닌 자의 진술을 기재한 조서로서 제312조 제4항에 따른다.", "그 안에 피고인 甲의 진술이 전문으로 기재되어 있으므로 제316조 제1항의 요건도 함께 갖추어야 한다."], "cases": ["2005도7601", "2015도12981"], "law": "제312조 제4항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "auto": "제316조 제1항", "form": "진술조서", "a1": "피고인", "a2": "피고인 아닌 자", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 피고인 아닌 자(乙)의 진술이 기재된 사경 등 작성의 진술조서 — 형식은 피의자신문조서이나 실질은 진술조서"}, {"id": 32, "tag": "대표이사의 출납 수첩", "facts": "회사 대표 甲은 업무상배임·배임수재로 기소되었다. 경찰이 영장으로 압수한 \"2025년도 대표이사 일일 출납 사항\" 수첩에는 날마다 손으로 적은 금전출납 내역과 영수증이 붙어 있다. 甲은 자신이 작성한 적이 없다며 증거로 함에 동의하지 않았으나, 필적감정 결과 甲의 필적으로 확인되었다.", "ev": "甲의 일일 출납 수첩", "kind": "전문", "notes": ["범죄사실의 인정 여부와 관계없이 자기에게 맡겨진 사무를 처리한 내역을 그때그때 계속적·기계적으로 적은 문서는 제315조 제2호의 업무상 통상문서로서 당연히 증거능력이 있다.", "업무의 기계적 반복성 때문에 허위가 개입할 여지가 적어 반대신문이 필요 없기 때문이다. 필적감정으로 진정성립이 증명되었으므로 제313조 제2항(진술서)으로도 증거능력을 인정할 수 있다."], "cases": ["2018도13792", "94도2865"], "law": "제315조 제2호", "opts": ["제312조 제3항", "제313조 제1항", "제314조", "제315조 제1호", "제315조 제2호", "없음"], "why": "제315조 제2호 (또는 이에 준하는 것)"}, {"id": 33, "tag": "세관공무원의 시가감정서", "facts": "피고인 甲은 밀수입으로 인한 관세법위반으로 기소되었다. 세관공무원이 직무상 작성한 범칙물자 시가감정서가 증거로 제출되었고, 甲은 증거로 함에 동의하지 않는다.", "ev": "세관공무원이 작성한 범칙물자 시가감정서", "kind": "전문", "notes": ["공무원이 직무상 증명할 수 있는 사항에 관하여 작성한 문서는 제315조 제1호에 따라 당연히 증거능력이 있다.", "다만 수사기관이 작성한 수사 관련 서류나 국립과학수사연구원의 감정의뢰회보서는 이에 해당하지 않는다."], "cases": ["85도225"], "law": "제315조 제1호", "opts": ["제312조 제4항", "제313조 제1항", "제314조", "제315조 제1호", "제315조 제3호", "없음"], "why": "제315조 제1호 (또는 이에 준하는 것)"}, {"id": 34, "tag": "DNA 감정의뢰회보서", "facts": "피고인 甲은 살인으로 기소되었다. 검사는 범행 현장에서 甲의 DNA가 확인되었다는 국립과학수사연구원의 감정의뢰회보서를 증거로 제출하였고, 甲은 증거로 함에 동의하지 않는다.", "ev": "국립과학수사연구원의 감정의뢰회보서", "kind": "전문", "notes": ["국립과학수사연구원(소)장의 감정의뢰회보는 당연히 증거능력이 있는 서류(제315조)가 아니다.", "감정의 경과와 결과를 기재한 서류로서 제313조 제3항에 따라 제1항·제2항이 준용되므로, 작성자인 감정인의 진술로 성립의 진정이 증명되어야 증거능력이 있다(부인하면 객관적 방법으로 증명)."], "cases": ["99도4036"], "law": "제313조 제3항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제3항", "제314조", "제315조 제1호", "없음"], "why": "감정의 결과를 기재한 서류"}, {"id": 35, "tag": "구속적부심문조서", "facts": "피고인 甲은 구속적부심사 심문기일에서 \"피해자를 때린 것은 맞다\"고 진술하였다. 그 구속적부심문조서가 공판에 증거로 제출되었고, 甲은 증거로 함에 동의하지 않는다.", "ev": "甲의 진술이 기재된 구속적부심문조서", "kind": "전문", "notes": ["구속적부심문조서는 제311조가 규정한 조서(공판준비·공판기일 조서)에는 해당하지 않는다.", "그러나 특히 신용할 만한 정황에 의하여 작성된 문서이므로 피고인이 부동의해도 제315조 제3호에 따라 당연히 증거능력이 있다. 구속 전 피의자심문조서도 같다."], "cases": ["2003도5693", "99도2317"], "law": "제315조 제3호", "opts": ["제311조", "제312조 제4항", "제313조 제1항", "제314조", "제315조 제3호", "없음"], "why": "제315조 제3호 (또는 이에 준하는 것)"}, {"id": 36, "tag": "개인병원 의사의 상해진단서", "facts": "피고인 甲의 상해 사건에서, 피해자를 진료한 개인병원 의사 B가 작성한 상해진단서가 증거로 제출되었다. 甲은 증거로 함에 동의하지 않는다.", "ev": "의사 B가 작성한 상해진단서", "kind": "전문", "notes": ["사인인 의사가 작성한 진단서는 공무원의 직무상 증명문서(제315조 제1호)나 업무상 통상문서(제315조 제2호, 진료기록부·진료일지는 해당)가 아니다.", "피고인 아닌 자가 작성한 진술서로서 제313조 제1항에 따라 작성자인 의사의 진술로 성립의 진정이 증명되어야 한다(부인하면 제313조 제2항)."], "cases": [], "law": "제313조 제1항", "opts": ["제312조 제4항", "제313조 제1항", "제314조", "제315조 제1호", "제315조 제2호", "없음"], "form": "진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(의사 B)가 작성한 진술서"}, {"id": 37, "tag": "전화 통화 수사보고서", "facts": "검찰주사보는 외국에 사는 참고인 丙과 전화로 통화하면서 \"甲에게 돈을 빌려준 적이 없다\"는 丙의 말을 문답 형식으로 적은 수사보고서를 작성하였다. 보고서에는 검찰주사보의 기명날인만 있고 丙의 서명이나 날인은 없다. 甲은 증거로 함에 동의하지 않는다.", "ev": "참고인 丙과의 전화 통화 내용을 적은 수사보고서", "kind": "전문", "notes": ["이 수사보고서는 제311조·제312조·제315조·제316조의 적용 대상이 아니므로, 결국 제313조의 진술을 기재한 서류에 해당해야 제314조도 문제될 수 있다.", "그런데 원진술자 丙의 서명이나 날인이 없어 제313조의 서류에 해당하지 않으므로, 제314조를 따질 것도 없이 증거능력이 없다."], "cases": ["98도2742", "2010도5610"], "law": "없음", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "why": "예외 규정이 마련되지 않은 전문증거"}, {"id": 38, "tag": "경찰 검증조서와 현장 사진", "facts": "피고인 甲의 살인 사건에서, 사법경찰관이 작성한 검증조서에는 범행 현장의 상황이 기재되어 있고 현장을 촬영한 사진이 첨부되어 있다. 甲은 증거로 함에 동의하지 않는다.", "ev": "사법경찰관 작성 검증조서(현장 상황 기재 부분과 첨부된 현장 사진)", "kind": "전문", "notes": ["수사기관의 검증조서는 적법한 절차와 방식에 따라 작성되고 작성자의 진술로 성립의 진정이 증명되면 증거능력이 있다(제312조 제6항). 작성자는 검증조서를 작성한 사람이고, 검증에 참여만 한 사람은 해당하지 않는다.", "첨부된 사진·도화는 검증조서와 일체로 판단한다. 검증 결과를 적은 서류는 작성자가 직접 관찰한 결과를 스스로 기재한 것이므로 이 Drill에서는 진술서에 준하는 것으로 분류했다."], "cases": ["76도500", "90도1303"], "law": "제312조 제6항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제6항", "제313조 제1항", "제314조", "없음"], "form": "검증조서", "alt": [], "by": "사경 등", "why": "사경 등 작성의 검증조서 (현장 상황 기재 부분과 첨부된 현장 사진)"}, {"id": 40, "tag": "신문에 동석한 어머니의 대답", "facts": "경찰은 청각장애가 있는 피의자 甲을 신문하면서 甲의 어머니 B를 동석시켰다. 피의자신문조서 일부에는 B가 甲을 대신해 \"아들이 그날 가게에 들어간 것은 맞다\"고 답한 내용이 적혀 있다. 甲은 증거로 함에 동의하지 않는다.", "ev": "甲에 대한 피의자신문조서 중 동석자 B가 대신 진술한 부분", "kind": "전문", "notes": ["피의자신문에 동석한 사람(제244조의5)이 피의자를 대신하여 진술한 부분은 그 동석자의 진술을 기재한 조서에 해당한다.", "따라서 피고인 아닌 자의 진술조서로서 제312조 제4항의 요건을 갖추어야 한다."], "cases": ["2009도1322"], "law": "제312조 제4항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "없음"], "form": "진술조서", "a": "피고인 아닌 자", "alt": [], "by": "사경 등", "why": "피고인 아닌 자(동석자 B)의 진술을 내용으로 하는 사경 등 작성의 진술조서 — 형식은 피의자신문조서이나 실질은 진술조서"}, {"id": 41, "tag": "미군 수사관의 수사보고서", "facts": "피고인 甲은 미군 기지 안에서 저지른 범행으로 기소되었다. 미국 육군 범죄수사대(CID) 수사관이 甲을 조사하면서 甲의 자백을 기재한 수사보고서가 증거로 제출되었고, 甲은 법정에서 그 내용을 부인한다.", "ev": "CID 수사관이 작성한 수사보고서 중 甲의 자백 기재 부분", "kind": "전문", "notes": ["제312조 제3항의 '검사 이외의 수사기관'에는 특별한 사정이 없는 한 외국의 권한 있는 수사기관도 포함된다.", "따라서 미국 범죄수사대·연방수사국 수사관이 작성한 수사보고서나 피고인이 수사과정에서 작성한 진술서는 피고인이 내용을 부인하면 증거로 쓸 수 없다(피의자신문조서에 준하는 것)."], "cases": ["2003도6548"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서"}, {"id": 42, "tag": "다른 사건 때의 경찰 조서", "facts": "피고인 甲은 횡령으로 기소되었다. 검사는 甲이 2년 전 별개의 사기 사건으로 경찰 조사를 받을 때 \"그때 받은 돈 일부를 乙에게 주었다\"고 진술한 피의자신문조서를 증거로 제출하였고, 甲은 그 내용을 부인한다.", "ev": "별개 사건에서 사법경찰관이 작성한 甲에 대한 피의자신문조서", "kind": "전문", "notes": ["제312조 제3항은 당해 사건에서 피의자였던 피고인에 대한 조서뿐 아니라, 전혀 별개의 사건에서 피의자였던 피고인에 대한 검사 이외의 수사기관 작성 피의자신문조서에도 적용된다.", "따라서 피고인이 내용을 부인하면 증거능력이 없다."], "cases": ["94도2287"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서"}, {"id": 43, "tag": "피고인의 일기장", "facts": "피고인 甲의 절도 사건에서, 甲의 집에서 압수된 甲의 자필 일기장에 \"오늘 편의점에서 담배를 훔쳤다\"는 기재가 있다. 甲은 증거로 함에 동의하지 않는다.", "ev": "甲이 자필로 쓴 일기장의 해당 기재", "kind": "전문", "notes": ["수사과정 외에서 피고인이 스스로 쓴 일기·메모·편지는 피고인의 진술서로서 제313조 제1항이 적용된다. 작성자인 피고인의 진술로 성립의 진정이 증명되거나, 부인하면 필적감정 등 객관적 방법으로 증명되어야 한다(제313조 제2항).", "판례는 피고인의 자필 진술서에도 제313조 제1항 단서의 특신상태를 요구한다."], "cases": ["2000도1743"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술서", "a": "피고인", "alt": [], "why": "피고인(甲)이 작성한 진술서"}, {"id": 44, "tag": "협박 문자를 찍은 사진", "facts": "피고인 甲은 피해자에게 공포심을 일으키는 문자를 반복해 보낸 정보통신망법위반으로 기소되었다. 검사는 피해자의 휴대전화 화면에 표시된 그 문자들을 촬영한 사진을 증거로 제출하였다.", "ev": "피해자 휴대전화 화면의 문자를 촬영한 사진", "kind": "비진술", "notes": ["휴대전화에 저장된 문자정보가 범행의 직접적인 수단일 뿐 경험자의 진술을 대신하는 것이 아니면 전문법칙이 적용될 여지가 없다.", "다만 사진(사본)으로 쓰려면 휴대전화를 법정에 내기 어려운 사정이 있고, 사진의 영상이 화면의 문자정보와 정확히 같다는 점이 증명되어야 한다."], "cases": ["2006도2556"]}, {"id": 45, "tag": "피해자가 동생에게 보낸 문자", "facts": "피고인 甲은 공갈로 기소되었다. 피해자 丁은 甲에게서 풀려난 날 동생에게 \"甲에게 협박당해 돈을 뜯겼다\"는 내용으로 도움을 요청하는 문자를 보냈고, 그 문자를 촬영한 사진이 증거로 제출되었다. 甲은 증거로 함에 동의하지 않는다.", "ev": "丁이 동생에게 보낸 문자를 촬영한 사진", "kind": "전문", "notes": ["피해를 입은 내용을 알리는 문자는 범행 수단이 아니라 피해자가 겪은 사실을 전하는 것이므로, 그 문자를 촬영한 사진은 피해자의 진술서에 준한다.", "제313조에 따라 작성자 丁이 법정에서 자신이 작성해 보낸 것임을 확인하고, 동생도 그 문자를 촬영한 사진임을 확인하면 성립의 진정이 증명된다."], "cases": ["2010도8735"], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(피해자 丁)가 작성한 진술서"}, {"id": 46, "tag": "교사 발언을 들은 편의점 점주", "facts": "피고인 甲은 10세인 A에게 \"丁의 무대의상을 훔쳐 오라\"고 시켜 절도교사로 기소되었다. 사법경찰관은 편의점 점주 C를 찾아가 \"甲이 A에게 그렇게 말하는 것을 들었다\"는 내용의 자필 진술서를 제출받았다. 甲은 증거로 함에 동의하지 않는다.", "ev": "편의점 점주 C가 작성한 진술서", "kind": "전문", "notes": ["甲의 말은 그 자체가 교사행위로서 원진술의 존재 자체가 요증사실이므로 본래증거이다. 따라서 C의 진술서는 전문진술이 기재된 서류(재전문)가 아니고 제316조 제1항도 적용되지 않는다.", "수사가 시작된 뒤 경찰관의 관여 아래 작성되었으므로, 작성 장소와 관계없이 '수사과정에서 작성한 진술서'로서 제312조 제5항(→ 제4항 준용)이 적용된다. 그 요건을 못 갖추어도 진술불능과 특신상태가 증명되면 제314조로 증거능력이 인정될 수 있다."], "cases": ["2022도9510", "2023도15133"], "law": "제312조 제5항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제5항", "제313조 제1항", "제315조 제3호", "없음"], "form": "수사기관에서 작성한 진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(편의점 점주 C)가 사경 등의 수사과정에서 작성한 진술서"}, {"id": 47, "tag": "진술분석관이 녹화한 면담 영상", "facts": "피고인 甲은 성폭력범죄로 기소되었다. 수사 중 검사가 성폭력처벌법 제33조에 따라 대검찰청 진술분석관에게 피해자 진술의 신빙성에 관한 의견을 조회하자, 진술분석관은 피해자를 면담하면서 그 내용을 녹화하였다. 검사는 이 영상녹화물을 증거로 제출하였고, 甲은 증거로 함에 동의하지 않는다.", "ev": "진술분석관이 피해자 면담을 녹화한 영상녹화물", "kind": "전문", "notes": ["진술분석관은 수사기관이 아니지만, 수사가 시작된 뒤 검사의 의견조회에 따라 수사기관의 관여나 영향 아래 녹화한 것이므로 수사과정 외에서 작성되었다고 볼 수 없어 제313조 제1항이 적용되지 않는다.", "또 수사기관이 작성한 피의자신문조서나 진술조서(제312조 제1항·제3항·제4항)가 아니고, 진술서(제312조 제5항)도 아니므로 제312조로도 증거능력을 인정할 수 없다. 결국 적용할 예외 규정이 없어 증거능력이 없다.", "증거의 성격은 피해자의 진술을 다른 사람이 기록한 것이므로 이 Drill에서는 진술조서에 준하는 것으로 분류했다."], "cases": ["2023도15133"], "law": "없음", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "why": "예외 규정이 마련되지 않은 전문증거"}, {"id": 48, "tag": "형사조정조서의 피의자 주장란", "facts": "피고인 甲에 대한 사기 고소 사건이 검찰청 형사조정에 회부되었다. 형사조정위원이 작성한 형사조정조서의 \"피의자의 주장\"란에는 \"돈을 빌린 것은 맞지만 갚을 생각이었다\"는 甲의 진술이 적혀 있다. 甲은 증거로 함에 동의하지 않는다.", "ev": "형사조정조서 중 피의자의 주장란 기재 부분", "kind": "전문", "notes": ["형사조정위원은 수사기관이 아니지만, 형사조정조서는 수사가 시작된 뒤 수사기관의 관여나 영향 아래 작성된 것이어서 수사과정 외에서 작성된 서류로 볼 수 없으므로 제313조 제1항으로 증거능력을 인정할 수 없다.", "수사기관이 작성한 조서가 아니고(제312조 제1항·제3항·제4항 X) '피고인 또는 피고인이 아닌 자가 작성한 진술서'도 아니므로(제312조 제5항 X) 제312조로도 인정할 수 없다. 적용할 예외 규정이 없어 증거능력이 없다."], "cases": ["2024도11314"], "law": "없음", "opts": ["제312조 제1항", "제312조 제3항", "제313조 제1항", "제314조", "제315조 제3호", "없음"], "why": "예외 규정이 마련되지 않은 전문증거"}, {"id": 49, "tag": "수사보고서에 적은 상처", "facts": "피고인 甲의 상해 사건에서, 경찰관 A가 작성한 수사보고서에 \"피해자는 왼쪽 눈 부위에 타박상이 있고 무릎에도 찰과상이 있다\"는 관찰 내용이 적혀 있다. 甲은 증거로 함에 동의하지 않는다.", "ev": "수사보고서 중 피해자의 상처 상태를 적은 부분", "kind": "전문", "notes": ["수사보고서에 검증의 결과에 해당하는 기재가 있더라도 실황조사서가 아니고, 제312조 제6항의 검증조서도 아니며, 제313조 제1항의 진술서나 진술을 기재한 서류도 아니다.", "따라서 피고인이 증거로 함에 동의하지 않는 한 그 기재 부분은 증거로 할 수 없다. 증거의 성격은 경찰관이 관찰한 결과를 스스로 적은 것이므로 진술서에 준하는 것으로 분류했다."], "cases": ["2000도2933"], "law": "없음", "opts": ["제312조 제4항", "제312조 제6항", "제313조 제1항", "제314조", "제315조 제1호", "없음"], "why": "예외 규정이 마련되지 않은 전문증거"}, {"id": 50, "tag": "실황조사서 속 범행 재연", "facts": "피고인 甲은 상해치사로 기소되었다. 甲은 경찰에서 범행을 자백한 뒤 사법경찰관과 함께 현장에 나가 \"여기서 피해자의 멱살을 잡고 벽으로 밀쳤다\"고 설명하며 범행을 재연하였다. 사법경찰관은 그 설명과 재연 과정을 촬영한 사진을 실황조사서에 담았다. 甲은 법정에서 경찰에서의 자백과 재연 내용을 모두 부인한다.", "ev": "사법경찰관 작성 실황조사서 중 甲의 진술 기재 부분과 범행 재연 사진", "kind": "전문", "notes": ["사법경찰관이 작성한 검증조서(실황조사서)에 피의자이던 피고인이 수사기관 앞에서 자백한 범행 내용을 현장에 따라 진술·재연한 내용이 기재되고 그 재연 과정을 촬영한 사진이 첨부되어 있다면, 피고인이 공판정에서 그 진술 내용과 범행 재연의 상황을 모두 부인하는 이상 증거능력이 없다.", "그 부분은 형식이 검증조서(실황조사서)라도 실질은 피고인의 진술을 기재한 것이므로 제312조 제6항이 아니라 사경 작성 피의자신문조서와 같이 제312조 제3항에 따른다."], "cases": ["2003도6548", "87도2692"], "law": "제312조 제3항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제312조 제6항", "제313조 제1항", "없음"], "form": "피의자신문조서", "a": "피고인", "alt": [], "by": "사경 등", "why": "피고인(甲)의 진술을 내용으로 하는 사경 등 작성의 피의자신문조서 — 실황조사서 중 진술 기재·범행 재연 부분"}, {"id": 51, "tag": "마약 시가조사보고서", "facts": "피고인 甲은 마약을 밀매하였다는 혐의로 기소되었다. 형의 가중 여부를 가리기 위해 검사는 보건복지부장관이 작성한 마약 시가조사보고서를 증거로 제출하였고, 甲은 증거로 함에 동의하지 않는다.", "ev": "보건복지부장관이 작성한 마약 시가조사보고서", "kind": "전문", "notes": ["보건복지부장관이 작성한 마약 시가조사보고서는 공무원이 직무상 증명할 수 있는 사항에 관하여 작성한 문서로서 제315조 제1호에 따라 당연히 증거능력이 있다."], "cases": ["67도544"], "law": "제315조 제1호", "opts": ["제312조 제4항", "제313조 제1항", "제313조 제3항", "제315조 제1호", "제315조 제2호", "없음"], "why": "제315조 제1호 (또는 이에 준하는 것)"}, {"id": 52, "tag": "일본 세관공무원의 감정서 등본", "facts": "피고인 甲은 일본에서 들여온 물품에 관한 관세법위반으로 기소되었다. 검사는 일본 세관공무원이 직무상 작성한 범칙물건감정서의 등본을 증거로 제출하였고, 甲은 증거로 함에 동의하지 않는다.", "ev": "일본 세관공무원이 작성한 범칙물건감정서 등본", "kind": "전문", "notes": ["제315조 제1호의 공무원에는 외국공무원도 포함된다. 따라서 일본 세관공무원이 직무상 작성한 범칙물건감정서의 등본도 공무원의 직무상 증명문서로서 당연히 증거능력이 있다.", "감정서라는 이름이 붙어 있어도 감정인이 작성한 제313조 제3항의 감정서가 아니라 공무원의 직무상 문서로 본다."], "cases": ["83도3145"], "law": "제315조 제1호", "opts": ["제312조 제4항", "제313조 제1항", "제313조 제3항", "제314조", "제315조 제1호", "없음"], "why": "제315조 제1호 (또는 이에 준하는 것)"}, {"id": 53, "tag": "성매매업소 직원의 메모리카드", "facts": "피고인 甲은 성매매업소를 운영하며 성매매를 알선한 혐의로 기소되었다. 업소 직원 乙은 영업에 참고하기 위하여 성매매 상대방의 전화번호와 성매매 방법을 메모지에 적어 두었다가 이를 메모리카드에 입력해 두었는데, 수사기관이 이를 압수하였다. 甲은 증거로 함에 동의하지 않는다.", "ev": "직원 乙이 메모리카드에 입력해 둔 성매매 상대방의 전화번호와 성매매 방법 기재 내용", "kind": "전문", "notes": ["업소 직원이 영업에 참고하려고 성매매 상대방의 전화번호와 성매매 방법을 메모지에 적어 두었다가 메모리카드에 입력한 내용은, 영업상 필요로 그때그때 기계적으로 기재한 것으로서 업무상 필요로 작성한 통상문서(제315조 제2호)에 해당하여 당연히 증거능력이 있다.", "기록된 내용이 범죄행위(성매매)에 관한 것이라도 업무 수행 과정에서 계속적·기계적으로 작성된 것이면 업무상 통상문서가 될 수 있다."], "cases": ["2007도3219"], "law": "제315조 제2호", "opts": ["제313조 제1항", "제314조", "제315조 제1호", "제315조 제2호", "제315조 제3호", "없음"], "why": "제315조 제2호 (또는 이에 준하는 것)"}, {"id": 54, "tag": "개인 의사의 사체검안서", "facts": "피고인 甲은 살인으로 기소되었다. 사망한 피해자를 검안한 개인병원 의사 C가 작성한 사체검안서가 증거로 제출되었고, 甲은 증거로 함에 동의하지 않는다.", "ev": "의사 C가 작성한 사체검안서", "kind": "전문", "notes": ["사인인 의사가 작성한 사체검안서는 공무원의 직무상 증명문서(제315조 제1호)나 업무상 통상문서(제315조 제2호)가 아니다.", "피고인 아닌 자가 작성한 진술서로서 제313조 제1항에 따라 작성자인 의사의 진술로 성립의 진정이 증명되어야 증거로 할 수 있다(부인하면 제313조 제2항)."], "cases": [], "law": "제313조 제1항", "opts": ["제312조 제4항", "제313조 제1항", "제313조 제3항", "제315조 제1호", "제315조 제2호", "없음"], "form": "진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(의사 C)가 작성한 진술서"}, {"id": 55, "tag": "교통사고 실황조사서", "facts": "피고인 甲은 교통사고처리특례법위반으로 기소되었다. 사고 직후 사법경찰관은 현장에서 도로 상황, 차량의 정지 위치, 바퀴 자국 등을 조사하여 실황조사서를 작성하였고, 이 실황조사는 긴급을 요하여 영장 없이 하였으나 지체 없이 사후영장을 발부받았다. 甲은 증거로 함에 동의하지 않는다.", "ev": "사법경찰관이 작성한 교통사고 실황조사서", "kind": "전문", "notes": ["수사기관의 실황조사서는 검증조서의 일종이다. 사후영장을 발부받았거나 당사자의 승낙을 받아 적법하게 이루어진 실황조사의 결과를 기재한 실황조사서는 제312조 제6항에 따라, 적법한 절차와 방식에 따라 작성되고 작성자의 진술로 성립의 진정이 증명되면 증거능력이 있다.", "반대로 긴급처분으로 영장 없이 실황조사를 하고 사후영장을 발부받지 않았다면 그 실황조사서는 증거능력이 없다."], "cases": ["88도1399", "83도3006"], "law": "제312조 제6항", "opts": ["제312조 제3항", "제312조 제4항", "제312조 제6항", "제313조 제1항", "제315조 제1호", "없음"], "form": "검증조서", "alt": [], "by": "사경 등", "why": "사경 등 작성의 검증조서 (교통사고 실황조사서)"}, {"id": 56, "tag": "사망한 참고인의 조서 속 다른 사람의 말", "facts": "피고인 甲의 사기 사건에서, 참고인 B는 검사 앞에서 \"丙이 나에게 '甲이 돈을 가로챘다'고 말해 주었다\"고 진술하였다. B는 그 뒤 사망하였고, 丙은 증인소환장을 송달받고도 법정에 출석하지 않았다. 甲은 증거로 함에 동의하지 않는다.", "ev": "검사가 작성한 B에 대한 진술조서 중 丙의 말을 전한 부분", "kind": "재전문", "notes": ["피고인 아닌 자(丙)의 진술을 내용으로 하는 피고인 아닌 자(B)의 진술을 기재한 조서는 제312조 제4항 또는 제314조의 요건과 함께 제316조 제2항의 요건을 갖추어야 증거능력이 있다.", "조서 부분은 B가 사망하였으므로 제314조가 문제되고, 丙의 말을 전한 부분은 제316조 제2항이 적용된다. 그런데 원진술자 丙이 소환장을 받고도 출석하지 않은 것만으로는 사망·질병·외국거주·소재불명 등으로 진술할 수 없는 때에 해당하지 않아 제316조 제2항의 요건을 갖추지 못하므로 증거능력이 없다."], "cases": ["2015도12981", "96도575"], "law": "제314조", "opts": ["제312조 제1항", "제312조 제4항", "제313조 제1항", "제314조", "제315조 제3호", "없음"], "auto": "제316조 제2항", "form": "진술조서", "a1": "피고인 아닌 자", "a2": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(丙)의 진술을 내용으로 하는 피고인 아닌 자(참고인 B)의 진술이 기재된 진술조서"}, {"id": 57, "tag": "공동피고인의 말을 전한 참고인 조서", "facts": "피고인 甲과 공범 乙은 함께 기소되어 병합심리 중이다. 참고인 C는 검사 앞에서 \"乙이 나에게 '甲과 같이 훔쳤다'고 말했다\"고 진술하였다. 甲은 증거로 함에 동의하지 않는다.", "ev": "검사가 작성한 C에 대한 진술조서 중 乙의 말을 전한 부분", "kind": "재전문", "notes": ["제316조 제2항의 '피고인 아닌 자'에는 공범인 공동피고인도 포함된다. 따라서 C의 조서 중 乙의 말을 전한 부분은 제312조 제4항과 제316조 제2항의 요건을 모두 갖추어야 한다.", "원진술자 乙은 甲과 함께 재판을 받고 있어 법정에서 진술할 수 없는 때에 해당하지 않으므로, 제316조 제2항의 요건을 갖추지 못하여 증거능력이 없다."], "cases": ["2019도11552"], "law": "제312조 제4항", "opts": ["제312조 제1항", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제314조", "없음"], "auto": "제316조 제2항", "form": "진술조서", "a1": "공범인 공동피고인", "a2": "피고인 아닌 자", "alt": [], "by": "검사", "why": "공범인 공동피고인(乙)의 진술을 내용으로 하는 피고인 아닌 자(참고인 C)의 진술이 기재된 검사 작성의 진술조서"}, {"id": 58, "tag": "다른 사건 공판조서 속 공범의 진술", "facts": "피고인 甲의 사기 사건에서, 공범 丙은 먼저 따로 기소되어 재판을 받았는데 그 사건 공판기일에 피고인으로서 \"甲과 함께 범행하였다\"고 진술하였다. 검사는 丙 사건의 공판조서를 증거로 제출하였고, 甲은 증거로 함에 동의하지 않는다.", "ev": "공범 丙에 대한 다른 사건 공판조서 중 丙이 피고인으로서 한 진술 기재 부분", "kind": "전문", "notes": ["다른 사건에서 공범이 피고인으로서 한 진술을 기재한 공판조서는 제315조 제3호의 '기타 특히 신용할 만한 정황에 의하여 작성된 문서'로서 당연히 증거능력이 있다.", "당해 사건의 공판조서가 아니므로 제311조가 아니다."], "cases": ["64도135", "65도372"], "law": "제315조 제3호", "opts": ["제311조", "제312조 제3항", "제312조 제4항", "제313조 제1항", "제315조 제3호", "없음"], "why": "제315조 제3호 (또는 이에 준하는 것)"}, {"id": 59, "tag": "증언을 뒤집은 검찰 진술조서", "facts": "피고인 甲의 사기 사건에서 증인 C는 법정에서 甲에게 유리한 증언을 마쳤다. 그 뒤 검사는 C를 소환하여 증언 내용을 추궁한 끝에 이를 번복하는 취지의 진술을 받아 진술조서를 작성하였다. 甲은 증거로 함에 동의하지 않는다.", "ev": "증언을 마친 C를 검사가 다시 조사하여 작성한 진술조서", "kind": "전문", "notes": ["형식상 피고인 아닌 자의 진술을 기재한 검사 작성 진술조서(제312조 제4항)이다.", "그러나 이미 증언을 마친 증인을 소환하여 증언을 번복시키는 방식으로 작성한 진술조서는 공판중심주의·직접주의에 어긋나므로 피고인이 동의하지 않는 한 증거능력이 없다. C가 다시 법정에 나와 그 조서의 진정성립을 인정하고 반대신문 기회가 주어져도 마찬가지이며, 다만 C의 새 법정증언 자체는 증거가 될 수 있다."], "cases": ["99도1108", "2017도1660"], "law": "제312조 제4항", "opts": ["제312조 제1항", "제312조 제4항", "제313조 제1항", "제314조", "제316조 제2항", "없음"], "form": "진술조서", "a": "피고인 아닌 자", "alt": [], "by": "검사", "why": "피고인 아닌 자(증인 C)의 진술을 내용으로 하는 검사 작성의 진술조서 — 증언 번복 진술조서(판례상 동의 없으면 증거능력 없음)"}, {"id": 60, "tag": "피해자의 피해신고서 사본", "facts": "피고인 甲의 절도 사건에서, 피해자 A가 직접 작성한 피해신고서의 사본이 증거로 제출되었다. 甲은 증거로 함에 동의하지 않고, A는 법정에 나오지 않았다.", "ev": "피해자 A가 작성한 피해신고서 사본", "kind": "전문", "notes": ["피해자가 작성한 피해신고서는 피고인 아닌 자가 작성한 진술서로서 제313조 제1항 본문(수사과정에서 작성했다면 제312조 제5항·제4항)의 요건을 갖추어야 한다.", "A가 법정에서 진정성립을 인정하지 않았으므로 증거능력이 없다."], "cases": [], "law": "제313조 제1항", "opts": ["제312조 제4항", "제312조 제5항", "제313조 제1항", "제314조", "제315조 제2호", "없음"], "form": "진술서", "a": "피고인 아닌 자", "alt": [], "why": "피고인 아닌 자(피해자 A)가 작성한 진술서"}];
